// Respond accepts only a ticket polled here; host principal/deadline checks still apply.
func (s *Ros2Dobot_msgs_v4SrvAIServer) Respond(id uint64, value Ros2Dobot_msgs_v4SrvAI_Response) error {
	if s == nil || s.core == nil {
		return rpcError(ros.BadHandle)
	}
	wire, err := value.Encode()
	if err != nil {
		return err
	}
	return s.core.respond(id, -1, wire)
}

// SpinOnce executes one handler under a lease. Return a value, do not also respond manually.
// Normal errors/panic unwinding release the lease; Wasm abort cannot promise cleanup.
func (s *Ros2Dobot_msgs_v4SrvAIServer) SpinOnce(handler func(uint64, Ros2Dobot_msgs_v4SrvAI_Request) (Ros2Dobot_msgs_v4SrvAI_Response, error)) error {
	if s == nil || s.core == nil {
		return rpcError(ros.BadHandle)
	}
	if handler == nil {
		return rpcError(ros.Invalid)
	}
	if err := s.core.owners.idle(); err != nil {
		return err
	}
	s.core.owners.busy = true
	defer func() { s.core.owners.busy = false }()
	id, value, err := s.pollInner()
	if err != nil {
		return err
	}
	response, err := handler(id, value)
	if err != nil {
		return err
	}
	return s.Respond(id, response)
}

